// Reports the failed run to Convex, for the admin Automations page. The id is the
// failed run's id, so if this report is ever repeated, Convex records it once.
const crypto = require('crypto');
const { execution, workflow } = $input.first().json;
const executionId = String(execution.id ?? Date.now());
const body = JSON.stringify({
  id: `error:${executionId}`,
  type: 'workflow.failed',
  workflowName: workflow.name,
  nodeName: execution.lastNodeExecuted,
  message: execution.error?.message ?? 'Unknown error',
  executionId,
  executionUrl: execution.url,
});
const timestamp = Math.floor(Date.now() / 1000).toString();
const signature =
  'sha256=' +
  crypto.createHmac('sha256', $env.LENDLOOP_REQUESTS_SECRET).update(`${timestamp}.${body}`).digest('hex');
return [{ json: { body, timestamp, signature } }];
